/// <summary>
/// parmFromAutomation
/// </summary>
/// <param name = "_fromAutomation">_fromAutomation</param>
/// <returns>fromAutomation</returns>
public boolean metParmFromAutomation(boolean _metFromAutomation = metFromAutomation)
{
    metFromAutomation = _metFromAutomation;
    return metFromAutomation;
}

/// <summary>
/// CoC extension
/// </summary>
/// <returns>identifierName</returns>
public identifierName lastValueElementName()
{
    identifierName ret = next lastValueElementName();
    if(this.metFromAutomation)
    {
        ret = '';
    }
    return ret;
}

    /// <summary>
    /// CoC extension
    /// </summary>
    public void closeFile()
    {
        if(Global::isRunningOnBatch())
        {
            file = null;        // Do not attempt to send file to browser when running in batch.
            warning("@MET:FileNotGeneratedInBatch");
        }

        next closeFile();
    }
